fn load_inputs(args:&[String])->(Curve,jac::Curve,jac::Div,[Vec<Div>;2]){
 let input=fs::read_to_string(&args[2]).unwrap();let mut it=input.split_whitespace();assert_eq!(it.next(),Some("COLD_INPUT"));let ns:Vec<u64>=it.map(|s|s.parse().unwrap()).collect();assert_eq!(&ns[..2],&[3,P]);let ell=ns[2];let mut at=3;let mut ps=vec![];for _ in 0..5{let n=ns[at]as usize;at+=1;ps.push(Poly::from_coeffs(&ns[at..at+n]));at+=n;}assert_eq!(at,ns.len());let refc=jac::Curve::new(Fp::new(P),ps[0]);let d1=jac::Div{u:ps[1],v:ps[2]};assert!(refc.is_valid(&d1)&&!refc.is_zero(&d1)&&refc.is_zero(&refc.mul(&d1,ell)));
 let text=fs::read_to_string(&args[1]).unwrap();let fieldline:Vec<u64>=text.lines().next().unwrap().split_whitespace().skip(1).map(|s|s.parse().unwrap()).collect();assert_eq!(&fieldline[..2],&[P,13]);let field=Field{c:fieldline[2],q:(P as u128).pow(13)};assert!(field.irreducible());let c=Curve{field,f:Pol::embed(&refc.f)};let mut ks=[vec![],vec![]];
 for line in text.lines().skip(1){let ns:Vec<u64>=line.split_whitespace().skip(1).map(|s|s.parse().unwrap()).collect();let k=ns[0]as usize;assert!(k<2);assert_eq!(ns[1]as usize,ks[k].len());let mut at=2;let mut ps=vec![];for _ in 0..2{let n=ns[at]as usize;assert!(n<=4);at+=1;let mut v=vec![];for _ in 0..n{let e=std::array::from_fn(|i|ns[at+i]);at+=13;assert!(e.iter().all(|&x|x<P));v.push(e);}let p=Pol::new(v);assert_eq!(p.0.len(),n);ps.push(p);}assert_eq!(at,ns.len());let d=Div{u:ps[0].clone(),v:ps[1].clone()};assert!(c.valid(&d)&&c.is_zero(&c.small(&d,3)));ks[k].push(d);}
 assert!(ks.iter().all(|s|s.len()==27));(c,refc,d1,ks)
}
